sys_ui_action.script:
function RemoveMakerTask() {

    //MSSCUSTODY-3546

    //	gs.getSession().getUrlOnStack().indexOf('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction') > -1 && RP.isRelatedList() &&parent.bulk_task_type=="Maker"&&current.trade_task_type!="Checker";

    var task_no = g_list.getChecked(); //array of selected task's sys_ids from list
    var sysIds = task_no.split(",");
    var bulk_ID = g_form.getDisplayValue("bulk_id");

    if (sysIds != "") {

        var answer = confirm('You have selected' + ' ' + sysIds.length + ' ' + 'Tasks from : ' + bulk_ID + ' . Do you want to proceed?');
        if (answer == true) {

            var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkProcessUtils'); //MSSOTIQUBE-2539 --> calling SI MSSCustodyBulkProcessUtils
            ga.addParam('sysparm_name', 'RemoveMakerTask');
            ga.addParam('sysparm_bulkID', g_form.getUniqueValue("bulk_id"));
            ga.addParam('sysparm_taskID', task_no); //MSSOTIQUBE-1889
            ga.getXMLAnswer(getRequiredInc);

            function getRequiredInc(response) {
                location.reload(); //reload the form
            }

        } else {
            location.reload();
        }
    }
}
